const sortByPrice = () => {
  const grid = morse.$("#__next > div:nth-of-type(2) > main > div:nth-of-type(2) > div");
  if (!grid) return;
  const priceOf = card => {
    for (const el of card.querySelectorAll("*")) {
      if (el.children.length === 0 && /^\$[\d,]+(\.\d+)?$/.test(el.textContent.trim())) {
        return parseFloat(el.textContent.replace(/[^\d.]/g, ""));
      }
    }
    return Infinity;
  };
  Array.from(grid.children)
    .sort((a, b) => priceOf(a) - priceOf(b))
    .forEach(card => grid.appendChild(card));
};

morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", row => {
  if (row.querySelector(".morse-sort-price")) return;
  row.appendChild(morse.el("button", {
    class: "morse-sort-price",
    text: "Sort: price low to high",
    on: { click: sortByPrice }
  }));
});

morse.store.set("sortPrice", morse.store.get("sortPrice") || "off");

function parsePrice(card) {
  const t = card.querySelector("div:nth-of-type(2) > div:nth-of-type(3)")?.textContent || "";
  const m = t.replace(/,/g, "").match(/\d+(\.\d+)?/);
  return m ? parseFloat(m[0]) : Infinity;
}

function applySort() {
  const grid = morse.$("#__next > div:nth-of-type(2) > main > div:nth-of-type(2)");
  if (!grid) return;
  const cards = Array.from(grid.children);
  const sorted = cards.slice().sort((a, b) => parsePrice(a) - parsePrice(b));
  sorted.forEach(c => grid.appendChild(c));
}

const bar = morse.el("div", { style: "display:flex;justify-content:flex-end;margin:0 0 10px" },
  morse.el("button", {
    type: "button",
    "aria-pressed": "false",
    text: "Sort by price: low to high",
    style: "font:inherit;font-size:13px;padding:6px 12px;border:1px solid rgb(214,211,209);border-radius:6px;background:rgb(255,255,255);color:rgb(28,25,23);cursor:pointer",
    on: {
      click: (e) => {
        const btn = e.currentTarget;
        const on = btn.getAttribute("aria-pressed") !== "true";
        btn.setAttribute("aria-pressed", String(on));
        btn.style.background = on ? "rgb(28,25,23)" : "rgb(255,255,255)";
        btn.style.color = on ? "rgb(250,250,249)" : "rgb(28,25,23)";
        morse.store.set("sortPrice", on ? "on" : "off");
        if (on) applySort();
      }
    }
  })
);

morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", el => {
  if (!el.nextElementSibling || !el.nextElementSibling.matches("[data-sort-bar]")) {
    bar.setAttribute("data-sort-bar", "");
    el.insertAdjacentElement("afterend", bar);
  }
});

morse.every(500, () => {
  if (morse.store.get("sortPrice") === "on") applySort();
});

morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(2) > div", (grid) => {
  if (grid.dataset.priceSorted) return;
  grid.dataset.priceSorted = "1";
  morse.store.set("priceSorted", "1");
});

