    class: "all-off",
    type: "button",
    text: "All off",
    "aria-label": "Turn all devices off",
    on: { click: () => {
      let n = 0;
      morse.$$("device-card >>> button:not([disabled])").forEach(b => {
        if (/: on$/.test(b.getAttribute("aria-label") || "")) { b.click(); n++; }
      });
      morse.toast(n ? `Turned off ${n} device${n === 1 ? "" : "s"}` : "Nothing to turn off");
    }}
  });
  h.after(btn);
});

